package com.technova.model;
import jakarta.persistence.*;
@Entity @Table(name="configuracion_tienda") public class ConfiguracionTienda { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_configuracion") private Long id; @Column(name="nombre_tienda") private String nombreTienda; private String ruc,telefono,whatsapp,email,direccion,horario; @Column(name="yape_numero") private String yapeNumero; @Column(name="plin_numero") private String plinNumero; @Column(name="mensaje_footer") private String mensajeFooter; public ConfiguracionTienda(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getNombreTienda(){return nombreTienda;} public void setNombreTienda(String v){nombreTienda=v;} public String getRuc(){return ruc;} public void setRuc(String v){ruc=v;} public String getTelefono(){return telefono;} public void setTelefono(String v){telefono=v;} public String getWhatsapp(){return whatsapp;} public void setWhatsapp(String v){whatsapp=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getDireccion(){return direccion;} public void setDireccion(String v){direccion=v;} public String getHorario(){return horario;} public void setHorario(String v){horario=v;} public String getYapeNumero(){return yapeNumero;} public void setYapeNumero(String v){yapeNumero=v;} public String getPlinNumero(){return plinNumero;} public void setPlinNumero(String v){plinNumero=v;} public String getMensajeFooter(){return mensajeFooter;} public void setMensajeFooter(String v){mensajeFooter=v;} }
